// Request to the CGI xhr = new XMLHttpRequest(); xhr.open('POST', "/cgi/RdDevRnd.cgi", true); xhr.setRequestHeader('Content-Type', 'application/x-www-form-urlencoded'); var FUNC = function() { ReadDeviceRandomTbl_Response(xhr, devtblid); }; // Response analysis function setting xhr.onreadystatechange = FUNC; xhr.send(param); }

// The function for analyzing a response function ReadDeviceRandomTbl_Response(xhr, devtblid) { // XMLHttpRequest Client status check // 0:UNSENT 1:OPENED 2:HEADERS_RECEIVED 3:LOADING 4:DONE if( 4 != xhr.readyState ) { // End the processing if the status 4 is other than DONE (operation complete). return; }

// HTTP Response code check if ( 200 != xhr.status ) { // End it if the response code is other than "200 OK". return; } var i, dataitem; var devtblitem = document.getElementById(devtblid); var tblrows = devtblitem.rows.length; // Obtain the number of the table lines (including the header). var res = JSON.parse( xhr.response ); // Analysis processing of JSON string

// Judgment from the CGI if( res.RET != "0000" ) { // Display the error dialog box if the result is abnormal. alert("ERROR=" + res.RET); } else { // Reflect the obtained value to the table if the result is normal. for ( i = 1, m = 0; i < tblrows; i++, m++) { dataitem = document.getElementById(devtblitem.rows[i].cells[2].childNodes[0].id); // Set the read result to the value of the table (convert the hexadecimal string to numerical value). dataitem.value = parseInt(res.DATA[m], 16); } alert("read complete"); } } </script> </head>

