<!DOCTYPE html> <html xmlns="http://www.w3.org/1999/xhtml"> <head> <!-- charset setting*Set UTF-8 which is set in the Web server setting --> <meta charset="UTF-8"> <meta http-equiv="X-UA-Compatible" content="IE=edge"/> <!-- Set the title name --> <title>Device write CGI sample</title> <!-- Write the JavaScript of the user here --> <script> function WriteDeviceBlockTbl(devtblid, row) { var dataitem; var xhr; var devtblitem = document.getElementById(devtblid); // Number of device points setting (fixed to one point) var param = 'NUM=1&'; // Parameter setting of the device name var devitem = document.getElementById(devtblitem.rows[row].cells[0].childNodes[0].id); param += 'DEV1=' + devitem.value + '&';

// Parameter setting of the device size var typitem = document.getElementById(devtblitem.rows[row].cells[1].childNodes[0].id); if( 'Bit' == typitem.value ) { param += 'TYP1=' + 'B'; } else if( '16-bit Integer' == typitem.value) { param += 'TYP1=' + 'W'; } else if( '32-bit Integer' == typitem.value) { param += 'TYP1=' + 'D'; } else { param += 'TYP1=' + 'Q'; } param += '&';

// Parameter setting of the data var dataitem = document.getElementById(devtblitem.rows[row].cells[2].childNodes[0].id); param += 'DATA1=' + parseInt(dataitem.value).toString(16)

// Request to the CGI xhr = new XMLHttpRequest(); xhr.open('POST', "/cgi/WrDev.cgi", true); xhr.setRequestHeader('Content-Type', 'application/x-www-form-urlencoded'); var FUNC = function() { WriteDeviceBlockTbl_Response(xhr, typitem, dataitem); }; // Response analysis function setting xhr.onreadystatechange = FUNC; xhr.send(param); }

// The function for analyzing a response function WriteDeviceBlockTbl_Response(xhr, typitem, dataitem) { // XMLHttpRequest Client status check // 0:UNSENT 1:OPENED 2:HEADERS_RECEIVED 3:LOADING 4:DONE if( 4 != xhr.readyState ) { // End the processing if the status 4 is other than DONE (operation complete). return; } // HTTP Response code check if ( 200 != xhr.status ) { // End it if the response code is other than "200 OK". return; } var value; var res = JSON.parse( xhr.response ); // Analysis processing of JSON string // Judgment from the CGI if( res.RET != "0000" ) { // Display the error dialog box if the result is abnormal. alert("ERROR=" + res.RET); } else { // Reflect the write result value if the result is normal. dataitem.value = parseInt(res.DATA[0],16); alert("write complete"); } } </script> </head>
